import events from './events.json' with {type:'json'};

const ALLOWED_ARGS = ['cursor', 'page_size'];
const DEFAULT_PAGE_SIZE = 2;
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;

function encodeCursor(offset) {
  return Buffer.from(`o:${offset}`, 'utf8').toString('base64');
}

function decodeCursor(cursor) {
  let decoded;
  try {
    decoded = Buffer.from(cursor, 'base64').toString('utf8');
  } catch {
    throw new Error('Invalid cursor');
  }
  const m = /^o:(\d+)$/.exec(decoded);
  if (!m) throw new Error('Invalid cursor');
  const offset = Number(m[1]);
  if (!Number.isInteger(offset) || offset < 0 || offset >= events.length) {
    throw new Error('Invalid cursor');
  }
  return offset;
}

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events in source order with optional cursor pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: {
            type: 'string',
            description: 'Opaque pagination cursor returned by a previous events_list call.',
          },
          page_size: {
            type: 'integer',
            minimum: MIN_PAGE_SIZE,
            maximum: MAX_PAGE_SIZE,
            default: DEFAULT_PAGE_SIZE,
            description: `Number of events per page (${MIN_PAGE_SIZE}-${MAX_PAGE_SIZE}, default ${DEFAULT_PAGE_SIZE}).`,
          },
        },
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'events_list') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const a = args === null || args === undefined ? {} : args;
  if (typeof a !== 'object' || Array.isArray(a)) {
    throw new Error('Invalid arguments');
  }

  for (const key of Object.keys(a)) {
    if (!ALLOWED_ARGS.includes(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  let offset = 0;
  if ('cursor' in a) {
    if (typeof a.cursor !== 'string' || a.cursor.length === 0) {
      throw new Error('Invalid cursor');
    }
    offset = decodeCursor(a.cursor);
  }

  let pageSize = DEFAULT_PAGE_SIZE;
  if ('page_size' in a) {
    const ps = a.page_size;
    if (!Number.isInteger(ps) || ps < MIN_PAGE_SIZE || ps > MAX_PAGE_SIZE) {
      throw new Error(`page_size must be an integer between ${MIN_PAGE_SIZE} and ${MAX_PAGE_SIZE}`);
    }
    pageSize = ps;
  }

  const slice = events.slice(offset, offset + pageSize);
  const result = { events: slice };
  if (offset + pageSize < events.length) {
    result.next_cursor = encodeCursor(offset + pageSize);
  }
  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}

